<script setup lang="ts">
import ActualSealCatalog from './ActualSealCatalog.vue'
import {computed,ref} from 'vue';import {useRoute} from 'vue-router';import {IconHeart,IconHeartFilled,IconGridDots,IconLayoutGrid,IconArrowRight,IconChevronDown,IconShare} from '@tabler/icons-vue'
import Rect from './Rect.vue';import Art from './Art.vue';import {catalog,studio,referenceMode,globalSearch,toggleFavorite,shareLink,show} from './state';import {eras,eraCounts} from './data'
const route=useRoute(),selectedEra=ref('全部'),draftEra=ref('秦汉'),styleFilter=ref('秦汉古玺'),sort=ref('default'),material=ref(''),sizeSort=ref(''),appliedStyle=ref(''),list=ref(false),active=ref('han-01')
const filtered=computed(()=>{let rows=catalog.value.filter(r=>(selectedEra.value==='全部'||r.era===selectedEra.value.replace('印',''))&&(!globalSearch.value||r.name.includes(globalSearch.value)||r.material.includes(globalSearch.value))&&(!material.value||r.material.includes(material.value)));if(appliedStyle.value&&appliedStyle.value!=='秦汉古玺')return [];const rank=(r:any)=>['先秦','秦汉','魏晋','隋唐','宋元','明清','近现代'].indexOf(r.era);if(sort.value==='name')rows=[...rows].sort((a,b)=>rank(a)-rank(b));if(sort.value==='reverse')rows=[...rows].sort((a,b)=>rank(b)-rank(a));if(sort.value==='favorites')rows=[...rows].sort((a,b)=>Number(studio.value.favorites.includes(b.id))-Number(studio.value.favorites.includes(a.id)));if(sizeSort.value)rows=[...rows].sort((a,b)=>(parseFloat(a.size)-parseFloat(b.size))*(sizeSort.value==='asc'?1:-1));return rows.slice(0,10)})
const chosen=computed(()=>catalog.value.find(r=>r.id===active.value)||catalog.value[0])
function chooseEra(era:string){selectedEra.value=era;draftEra.value=era.replace('印','')}
</script>
<template>
<ActualSealCatalog v-if="!referenceMode"/><template v-else>
<Rect :x="170" :y="0" :w="1502" :h="245" plain><Art name="catalog-hero" alt="印谱数据库，山水与印章视觉题图"/></Rect>
<Rect :x="195" :y="252" :w="1119" :h="77" plain><div class="im-era-tabs"><button v-for="(e,i) in eras" :class="{active:selectedEra===e}" @click="chooseEra(e)"><strong>{{e}}</strong><small>{{referenceMode?eraCounts[i]:i?catalog.filter(r=>r.era===e.replace('印','')).length:catalog.length}}</small></button></div></Rect>
<Rect :x="186" :y="338" :w="257" :h="601" title="高级筛选"><div class="im-catalog-filters"><header><h2>高级筛选</h2><button @click="selectedEra='全部';draftEra='秦汉';material='';globalSearch='';appliedStyle='';sizeSort='' ">重置</button></header><h3>朝代分类 <IconChevronDown :size="17"/></h3><label v-for="(e,i) in ['先秦','秦汉','魏晋','隋唐','宋元','明清','近现代']" :class="{checked:draftEra===e}"><input type="radio" name="catalog-era" :value="e" v-model="draftEra"><span>{{e}}</span><small>{{referenceMode?eraCounts[i+1]:catalog.filter(r=>r.era===e).length}}</small></label><h3>篆刻流派 <IconChevronDown :size="17"/></h3><label v-for="(s,i) in ['秦汉古玺','汉文印','浙派','皖派','吴派','邓散木','赵之谦','其他']"><input type="radio" name="catalog-style" :value="s" v-model="styleFilter"><span>{{s}}</span><small>{{['2,348','1,206','834','682','956','312','498','1,184'][i]}}</small></label><details><summary>印文内容</summary><input v-model="globalSearch" placeholder="搜索印文" aria-label="筛选印文内容"></details><details><summary>尺寸范围</summary><p>图示尺寸来自参考素材，未核验实物。</p></details><details><summary>收藏来源</summary><select v-model="material" aria-label="材质筛选"><option value="">全部材质</option><option>铜质</option><option>玉质</option><option>青田石</option></select></details><button class="im-gold-button" @click="selectedEra=draftEra;appliedStyle=styleFilter">应用筛选</button></div></Rect>
<Rect :x="458" :y="344" :w="856" :h="42" plain><div class="im-catalog-toolbar"><h2>共 {{referenceMode&&selectedEra==='全部'&&!globalSearch?'2,348':filtered.length}} 件印章</h2><div class="im-sort"><button :class="{active:sort==='default'}" @click="sort='default'">综合排序</button><button :class="{active:sort==='name'}" @click="sort='name'">年代从早到晚</button><button :class="{active:sort==='reverse'}" @click="sort='reverse'">年代从晚到早</button><button @click="sort='favorites'" title="按本机收藏优先排序">收藏热度</button><select v-model="sizeSort" aria-label="按尺寸排序"><option value="">尺寸大小</option><option value="asc">小到大</option><option value="desc">大到小</option></select></div><button class="im-outline" :class="{active:!list}" @click="list=false"><IconLayoutGrid :size="16"/> 图文卡片</button><button class="im-outline" :class="{active:list}" @click="list=true"><IconGridDots :size="16"/> 展柜模式</button></div></Rect>
<Rect :x="458" :y="400" :w="856" :h="541" plain><div class="im-catalog-grid" :class="{cabinet:list}"><article v-for="item in filtered" :key="item.id" @mouseenter="active=item.id"><RouterLink :to="'/catalog/'+item.id"><Art :name="item.image" :alt="item.name+'参考图示'"/></RouterLink><button class="im-card-heart" :aria-label="'收藏'+item.name" :aria-pressed="studio.favorites.includes(item.id)" @click="toggleFavorite(item.id)"><IconHeartFilled v-if="studio.favorites.includes(item.id)"/><IconHeart v-else/></button><span class="im-era-tag">{{item.era}}印</span><h3>{{item.name}}</h3><div class="im-object-tags"><span>{{item.period}}</span><span>{{item.material}}</span></div><p>{{item.size}}</p><RouterLink class="im-outline im-details-link" :to="'/catalog/'+item.id">查看详情 <IconArrowRight :size="17"/></RouterLink></article><p v-if="!filtered.length" class="im-empty">{{appliedStyle&&appliedStyle!=='秦汉古玺'?'尚无该流派的审核标签，不能据此自动分类。':'没有匹配的图示内容，请调整筛选。'}}</p></div></Rect>
<Rect :x="1327" :y="258" :w="327" :h="350" title="精选推荐"><div class="im-catalog-feature"><h2>精选推荐 <span>镇馆之宝</span></h2><Art name="catalog-feature" alt="精选印章视觉概念参考"/><h3>{{chosen?.name||'汉委奴国王印'}}</h3><div class="im-object-tags"><span>{{chosen?.period}}</span><span>{{chosen?.material}}</span></div><p>日本国宝 · 中日文化交流见证</p><RouterLink class="im-gold-button" :to="'/catalog/'+(chosen?.id||'han-01')">查看详情 <IconArrowRight :size="18"/></RouterLink></div></Rect>
<Rect :x="1327" :y="615" :w="327" :h="324" title="印章信息"><div class="im-catalog-info"><h2>印章信息</h2><dl><dt>印文</dt><dd>{{chosen?.name}}</dd><dt>朝代</dt><dd>{{chosen?.period}}（参考图示）</dd><dt>类型</dt><dd>官印</dd><dt>材质</dt><dd>{{chosen?.material}}</dd><dt>尺寸</dt><dd>{{chosen?.size}}</dd><dt>现藏</dt><dd>参考图提供的信息，尚未核实</dd><dt>印文释读</dt><dd>{{chosen?.name}}</dd><dt>简介</dt><dd>方寸之间，记录文字与印文化。图示资料不作为馆藏鉴定依据。</dd></dl><div><button class="im-gold-button" @click="chosen&&toggleFavorite(chosen.id)"><IconHeart :size="16"/> 收藏</button><button class="im-outline" @click="shareLink('/catalog/'+chosen?.id)"><IconShare :size="16"/> 分享</button></div></div></Rect>
</template>
</template>
